// Captures NDJSON trace windows by driving the real host (src/host.impl.ts)
// with seeded random walks, one run per trace file.
// Usage: node spec/capture.ts  → writes spec/traces/walk-N.ndjson
import { mkdirSync, writeFileSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host } from '../src/host.impl.ts';

type Obs = { status: string; t0: string; t1: string; t2: string };

const observe = async (h: Host, id: string): Promise<Obs> => {
  const v = await h.run(id);
  return v ? { status: v.status, t0: v.task0, t1: v.task1, t2: v.task2 } : { status: 'none', t0: 'none', t1: 'none', t2: 'none' };
};

const ACTIONS: Array<[string, (h: Host, id: string, task: number) => Promise<unknown>]> = [
  ['START', (h, id) => h.start(id)],
  ['TASK_STARTED', (h, id, t) => h.taskStarted(id, t)],
  ['TASK_COMPLETED', (h, id, t) => h.taskCompleted(id, t)],
  ['TASK_FAILED', (h, id, t) => h.taskFailed(id, t)],
  ['TASK_EVICTED', (h, id, t) => h.taskEvicted(id, t)],
  ['TASK_REQUEUED', (h, id, t) => h.taskRequeued(id, t)],
  ['CANCEL', (h, id) => h.cancel(id)],
];
const TASKS = [0, 1, 2, 3, -1];

let seed = 12345;
const rand = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };

const dir = new URL('./traces/', import.meta.url);
mkdirSync(dir, { recursive: true });

for (let w = 0; w < 60; w++) {
  const h = await createHost();
  const lines: string[] = [];
  // Mostly-legal walks reach deep states; a quarter of steps are arbitrary.
  for (let i = 0; i < 25; i++) {
    const pre = await observe(h, 'r');
    const [name, fire] = i === 0 && w % 6 !== 0 ? ACTIONS[0] : ACTIONS[rand(ACTIONS.length)];
    const task = rand(4) === 0 ? TASKS[rand(TASKS.length)] : rand(3);
    const takesTask = name.startsWith('TASK_');
    await fire(h, 'r', task);
    const post = await observe(h, 'r');
    lines.push(JSON.stringify({ pre, action: name, data: takesTask ? { task } : {}, post }));
  }
  writeFileSync(new URL(`walk-${w}.ndjson`, dir), lines.join('\n') + '\n');
}
console.log('captured 60 traces');

