  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
};
const inFlight = (s) => s === 'queued' || s === 'running' || s === 'evicted';
const isFinal = (s) => s === 'completed' || s === 'failed' || s === 'cancelled';
const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.some((t) => t === 'failed')) return 'failed';
  if (ts.some(inFlight)) return 'running';
  return 'cancelled';
};

const taskDomain = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];
const taskSchema = { task: { type: 'number' } };

const taskAcceptor = (name) => (model) => (proposal, { reject, next }) => {
  if (model.status === 'none') return reject('unknown-run');
  if (isFinal(model.status)) return reject('run-final');
  const i = proposal.task;
  if (i !== 0 && i !== 1 && i !== 2) return reject('no-such-task');
  const [from, to] = MOVES[name];
  const ts = TASKS.map((k) => model[k]);
  if (ts[i] !== from) return reject('illegal-move');
  ts[i] = to;
  next.t0 = ts[0];
  next.t1 = ts[1];
  next.t2 = ts[2];
  next.status = derive(ts);
};

