// Rules the brief requires, stated independently of the spec's derive().

const STATUSES = ['queued', 'running', 'evicted', 'completed', 'failed', 'cancelled'];
const IN_FLIGHT = ['queued', 'running', 'evicted'];
const FINAL = ['completed', 'failed', 'cancelled'];
const tasks = (s) => [s.t0, s.t1, s.t2];
const same = (a, b) => a.status === b.status && a.t0 === b.t0 && a.t1 === b.t1 && a.t2 === b.t2;

const MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
};

export const stateInvariants = [
  { name: 'not-started-is-all-none',
    pred: (s) => (s.status === 'none') === tasks(s).every((t) => t === 'none') },
  { name: 'values-are-statuses',
    pred: (s) => s.status === 'none' || [s.status, ...tasks(s)].every((v) => STATUSES.includes(v)) },
  { name: 'uniform-tasks-give-that-status',
    pred: (s) => !(s.t0 === s.t1 && s.t1 === s.t2) || s.status === s.t0 },
  { name: 'completed-only-when-all-completed',
    pred: (s) => (s.status === 'completed') === tasks(s).every((t) => t === 'completed') },
  { name: 'failed-whenever-a-task-failed',
    pred: (s) => !tasks(s).includes('failed') || s.status === 'failed' },
  { name: 'never-completed-or-cancelled-with-task-in-flight',
    pred: (s) => !['completed', 'cancelled'].includes(s.status) || !tasks(s).some((t) => IN_FLIGHT.includes(t)) },
  { name: 'running-only-with-task-in-flight-and-none-failed',
    pred: (s) => s.status !== 'running' || (tasks(s).some((t) => IN_FLIGHT.includes(t)) && !tasks(s).includes('failed')) },
];

export const transitionInvariants = [
  { name: 'final-run-never-changes',
    pred: (pre, a, d, post) => !FINAL.includes(pre.status) || same(pre, post) },
  { name: 'start-only-creates-queued-run',
    pred: (pre, a, d, post) => a !== 'START' || same(pre, post) ||
      (pre.status === 'none' && post.status === 'queued' && tasks(post).every((t) => t === 'queued')) },
  { name: 'task-report-moves-exactly-the-named-task',
    pred: (pre, a, d, post) => {
      if (!MOVES[a] || same(pre, post)) return true;
      const [from, to] = MOVES[a];
      return [0, 1, 2].every((i) => (i === d.task
        ? tasks(pre)[i] === from && tasks(post)[i] === to
        : tasks(pre)[i] === tasks(post)[i]));
    } },
  { name: 'cancel-cancels-exactly-in-flight-tasks',
    pred: (pre, a, d, post) => a !== 'CANCEL' || same(pre, post) ||
      [0, 1, 2].every((i) => tasks(post)[i] === (IN_FLIGHT.includes(tasks(pre)[i]) ? 'cancelled' : tasks(pre)[i])) },
];

export const rejectionInvariants = [
  { name: 'unknown-run-refuses-all-but-start',
    pred: (s, a, d, v) => s.status !== 'none' || a === 'START' || v.rejected },
  { name: 'final-run-refuses-everything',
    pred: (s, a, d, v) => !FINAL.includes(s.status) || v.rejected },
  { name: 'bad-task-number-refused',
    pred: (s, a, d, v) => !MOVES[a] || [0, 1, 2].includes(d.task) || v.rejected },
  { name: 'cancel-refused-iff-nothing-in-flight-on-live-run',
    pred: (s, a, d, v) => a !== 'CANCEL' || s.status === 'none' || FINAL.includes(s.status) ||
      v.rejected === !tasks(s).some((t) => IN_FLIGHT.includes(t)) },
];

export default { stateInvariants, transitionInvariants, rejectionInvariants };

