import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('fresh system has no runs; commands on unknown runs are refused', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal(await h.run('a'), null);
});

test('start creates a queued run; duplicate start refused', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.start('a')).ok, false);
});

test('happy path to completed, then everything refused', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) assert.equal((await h.taskStarted('a', t)).ok, true);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskCompleted('a', 0);
  await h.taskCompleted('a', 1);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskCompleted('a', 2);
  assert.equal((await h.run('a'))!.status, 'completed');
  assert.equal((await h.start('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
});

test('failure makes the run failed, but it still accepts commands', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 1);
  await h.taskFailed('a', 1);
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.equal((await h.taskStarted('a', 0)).ok, true);
  assert.equal((await h.run('a'))!.status, 'failed');
});

test('retry: a failed task is queued again and the run can complete', async () => {
  const h = await createHost();
  await h.start('a');
  assert.equal((await h.taskRetried('a', 0)).ok, false);
  await h.taskStarted('a', 0);
  assert.equal((await h.taskRetried('a', 0)).ok, false);
  await h.taskFailed('a', 0);
  assert.equal((await h.taskRetried('a', 3)).ok, false);
  assert.deepEqual(await h.taskRetried('a', 0), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskCompleted('a', t); }
  assert.equal((await h.run('a'))!.status, 'completed');
  assert.equal((await h.taskRetried('a', 0)).ok, false);
});

test('all tasks failed: run failed, still retryable', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskFailed('a', t); }
  assert.equal((await h.run('a'))!.status, 'failed');
  assert.equal((await h.cancel('a')).ok, false); // nothing in flight
  assert.equal((await h.taskRetried('a', 2)).ok, true);
  assert.equal((await h.run('a'))!.status, 'failed');
});

test('cancel on a failed run keeps the failed task, which can be retried', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 0);
  await h.taskFailed('a', 0);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled' });
  await h.taskRetried('a', 0);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskStarted('a', 0);
  await h.taskCompleted('a', 0);
  assert.equal((await h.run('a'))!.status, 'cancelled');
  assert.equal((await h.taskStarted('a', 1)).ok, false);
});

test('eviction and requeue; all evicted gives evicted', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskEvicted('a', t); }
  assert.equal((await h.run('a'))!.status, 'evicted');
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.taskRequeued('a', 0)).ok, true);
  assert.equal((await h.run('a'))!.status, 'running');
});

test('cancel: in-flight become cancelled, completed stay', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 0);
  await h.taskCompleted('a', 0);
  await h.taskStarted('a', 1);
  await h.taskEvicted('a', 1);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
});

test('bad task numbers and bad moves are refused and change nothing', async () => {
  const h = await createHost();
  await h.start('a');
  const before = await h.run('a');
  for (const t of [3, -1, 1.5, NaN, '0' as unknown as number]) assert.equal((await h.taskStarted('a', t)).ok, false);
  assert.equal((await h.taskCompleted('a', 0)).ok, false);
  assert.equal((await h.taskRequeued('a', 0)).ok, false);
  assert.deepEqual(await h.run('a'), before);
});

test('systems are independent', async () => {
  const a = await createHost();
  const b = await createHost();
  await a.start('x');
  assert.equal(await b.run('x'), null);
});

'use strict';

// SAM v2 strict spec of one run's stateful core (src/host.impl.ts:
// stepStart / stepTask / stepCancel). status 'none' = run never started.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'none', t0: 'none', t1: 'none', t2: 'none' };

const TASKS = ['t0', 't1', 't2'];
const MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
  TASK_RETRIED: ['failed', 'queued'],
};
const inFlight = (s) => s === 'queued' || s === 'running' || s === 'evicted';
// a failed run still accepts commands (retry); only these refuse everything
const isClosed = (s) => s === 'completed' || s === 'cancelled';
const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.some((t) => t === 'failed')) return 'failed';
  if (ts.some(inFlight)) return 'running';
  return 'cancelled';
};

const taskDomain = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];
const taskSchema = { task: { type: 'number' } };

const taskAcceptor = (name) => (model) => (proposal, { reject, next }) => {
  if (model.status === 'none') return reject('unknown-run');
  if (isClosed(model.status)) return reject('run-closed');
  const i = proposal.task;
  if (i !== 0 && i !== 1 && i !== 2) return reject('no-such-task');
  const [from, to] = MOVES[name];
  const ts = TASKS.map((k) => model[k]);
  if (ts[i] !== from) return reject('illegal-move');
  ts[i] = to;
  next.t0 = ts[0];
  next.t1 = ts[1];
  next.t2 = ts[2];
  next.status = derive(ts);
};

const taskAction = () => ({ action: (data = {}) => ({ ...data }), schema: taskSchema, domain: taskDomain });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      t0: { type: 'string' },
      t1: { type: 'string' },
      t2: { type: 'string' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      TASK_STARTED: taskAction(),
      TASK_COMPLETED: taskAction(),
      TASK_FAILED: taskAction(),
      TASK_EVICTED: taskAction(),
      TASK_REQUEUED: taskAction(),
      TASK_RETRIED: taskAction(),
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
    },
    acceptors: {
      START: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'none') return reject('run-exists');
        next.status = 'queued';
        next.t0 = 'queued';
        next.t1 = 'queued';
        next.t2 = 'queued';
      },
      TASK_STARTED: taskAcceptor('TASK_STARTED'),
      TASK_COMPLETED: taskAcceptor('TASK_COMPLETED'),
      TASK_FAILED: taskAcceptor('TASK_FAILED'),
      TASK_EVICTED: taskAcceptor('TASK_EVICTED'),
      TASK_REQUEUED: taskAcceptor('TASK_REQUEUED'),
      TASK_RETRIED: taskAcceptor('TASK_RETRIED'),
      CANCEL: (model) => (proposal, { reject, next }) => {
        if (model.status === 'none') return reject('unknown-run');
        if (isClosed(model.status)) return reject('run-closed');
        const ts = TASKS.map((k) => model[k]);
        if (!ts.some(inFlight)) return reject('nothing-in-flight');
        const after = ts.map((t) => (inFlight(t) ? 'cancelled' : t));
        next.t0 = after[0];
        next.t1 = after[1];
        next.t2 = after[2];
        next.status = derive(after);
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  TASK_STARTED: (data = {}) => intents.TASK_STARTED(data),
  TASK_COMPLETED: (data = {}) => intents.TASK_COMPLETED(data),
  TASK_FAILED: (data = {}) => intents.TASK_FAILED(data),
  TASK_EVICTED: (data = {}) => intents.TASK_EVICTED(data),
  TASK_REQUEUED: (data = {}) => intents.TASK_REQUEUED(data),
  TASK_RETRIED: (data = {}) => intents.TASK_RETRIED(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
};

module.exports = { instance, init, actions, getState, setState };

