  next.t2 = ts[2];
  next.status = derive(ts);
};

const taskAction = () => ({ action: (data = {}) => ({ ...data }), schema: taskSchema, domain: taskDomain });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      t0: { type: 'string' },
      t1: { type: 'string' },
      t2: { type: 'string' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      TASK_STARTED: taskAction(),
      TASK_COMPLETED: taskAction(),
      TASK_FAILED: taskAction(),
      TASK_EVICTED: taskAction(),
      TASK_REQUEUED: taskAction(),
      TASK_RETRIED: taskAction(),
      CANCEL_TASK: taskAction(),
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
    },
    acceptors: {
      START: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'none') return reject('run-exists');
        next.status = 'queued';
        next.t0 = 'queued';
        next.t1 = 'queued';
        next.t2 = 'queued';
      },
      TASK_STARTED: taskAcceptor('TASK_STARTED'),
      TASK_COMPLETED: taskAcceptor('TASK_COMPLETED'),
      TASK_FAILED: taskAcceptor('TASK_FAILED'),
      TASK_EVICTED: taskAcceptor('TASK_EVICTED'),
      TASK_REQUEUED: taskAcceptor('TASK_REQUEUED'),
      TASK_RETRIED: taskAcceptor('TASK_RETRIED'),
      CANCEL_TASK: (model) => (proposal, { reject, next }) => {
        if (model.status === 'none') return reject('unknown-run');
        if (isClosed(model.status)) return reject('run-closed');
