62	export function deriveStatus(tasks: readonly Status[]): Status {
63	  if (tasks[0] === tasks[1] && tasks[1] === tasks[2]) return tasks[0];
64	  if (tasks.some((t) => t === 'failed')) return 'failed';
65	  if (tasks.some(inFlight)) return 'running';
66	  return 'cancelled';
67	}
