// Workflow run status: an in-memory host for runs of three tasks.

export type Outcome = { ok: true } | { ok: false; reason: string };

export type Status = 'queued' | 'running' | 'evicted' | 'completed' | 'failed' | 'cancelled';

export interface RunView {
  status: Status;
  task0: Status;
  task1: Status;
  task2: Status;
  paused: boolean;
}

export interface Host {
  start(run: string): Promise<Outcome>;
  taskStarted(run: string, task: number): Promise<Outcome>;
  taskCompleted(run: string, task: number): Promise<Outcome>;
  taskFailed(run: string, task: number): Promise<Outcome>;
  taskEvicted(run: string, task: number): Promise<Outcome>;
  taskRequeued(run: string, task: number): Promise<Outcome>;
  taskRetried(run: string, task: number): Promise<Outcome>;
  cancel(run: string): Promise<Outcome>;
  cancelTask(run: string, task: number): Promise<Outcome>;
  pause(run: string): Promise<Outcome>;
  resume(run: string): Promise<Outcome>;
  run(run: string): Promise<RunView | null>;
}

export type CreateHost = () => Promise<Host>;

type Tasks = [Status, Status, Status];

export interface RunState {
  status: Status;
  tasks: Tasks;
  paused: boolean;
}

export type TaskReport = 'taskStarted' | 'taskCompleted' | 'taskFailed' | 'taskEvicted' | 'taskRequeued' | 'taskRetried';

/** Each task report: the status it moves from, and the status it moves to. */
export const MOVES: Record<TaskReport, { from: Status; to: Status }> = {
  taskStarted: { from: 'queued', to: 'running' },
  taskCompleted: { from: 'running', to: 'completed' },
  taskFailed: { from: 'running', to: 'failed' },
  taskEvicted: { from: 'running', to: 'evicted' },
  taskRequeued: { from: 'evicted', to: 'queued' },
  taskRetried: { from: 'failed', to: 'queued' },
};

export function inFlight(s: Status): boolean {
  return s === 'queued' || s === 'running' || s === 'evicted';
}

export function isFinal(s: Status): boolean {
  return s === 'completed' || s === 'failed' || s === 'cancelled';
}

/** A run with this status refuses every command; a failed run can still be retried. */
export function isClosed(s: Status): boolean {
  return s === 'completed' || s === 'cancelled';
}

/** The run's status, derived from its three tasks. */
export function deriveStatus(tasks: readonly Status[]): Status {
  if (tasks[0] === tasks[1] && tasks[1] === tasks[2]) return tasks[0];
  if (tasks.some((t) => t === 'failed')) return 'failed';
  if (tasks.some(inFlight)) return 'running';
  return 'cancelled';
}

type Step = { ok: true; state: RunState } | { ok: false; reason: string };

function settle(state: RunState, tasks: Tasks): Step {
  return { ok: true, state: { status: deriveStatus(tasks), tasks, paused: state.paused } };
}

/** The pure transition of one run. `state` is undefined for a run never started. */
export function stepStart(state: RunState | undefined): Step {
  if (state) return { ok: false, reason: 'run already exists' };
  return { ok: true, state: { status: 'queued', tasks: ['queued', 'queued', 'queued'], paused: false } };
}

export function stepTask(state: RunState | undefined, report: TaskReport, task: unknown): Step {
  if (!state) return { ok: false, reason: 'unknown run' };
  if (isClosed(state.status)) return { ok: false, reason: `run is ${state.status}` };
  if (task !== 0 && task !== 1 && task !== 2) return { ok: false, reason: 'no such task' };
  if (report === 'taskStarted' && state.paused) return { ok: false, reason: 'run is paused' };
  const move = MOVES[report];
  if (state.tasks[task] !== move.from) {
    return { ok: false, reason: `task ${task} is ${state.tasks[task]}, not ${move.from}` };
  }
  const tasks = [...state.tasks] as Tasks;
  tasks[task] = move.to;
  return settle(state, tasks);
}

export function stepCancel(state: RunState | undefined): Step {
  if (!state) return { ok: false, reason: 'unknown run' };
  if (isClosed(state.status)) return { ok: false, reason: `run is ${state.status}` };
  if (!state.tasks.some(inFlight)) return { ok: false, reason: 'no task in flight' };
  return settle(state, state.tasks.map((t) => (inFlight(t) ? 'cancelled' : t)) as Tasks);
}

export function stepCancelTask(state: RunState | undefined, task: unknown): Step {
  if (!state) return { ok: false, reason: 'unknown run' };
  if (isClosed(state.status)) return { ok: false, reason: `run is ${state.status}` };
  if (task !== 0 && task !== 1 && task !== 2) return { ok: false, reason: 'no such task' };
  if (!inFlight(state.tasks[task])) return { ok: false, reason: `task ${task} is ${state.tasks[task]}` };
  const tasks = [...state.tasks] as Tasks;
  tasks[task] = 'cancelled';
  return settle(state, tasks);
}

/** Pausing only flips the flag; the run's status is unchanged. */
export function stepPause(state: RunState | undefined, paused: boolean): Step {
  if (!state) return { ok: false, reason: 'unknown run' };
  if (isClosed(state.status)) return { ok: false, reason: `run is ${state.status}` };
  if (state.paused === paused) return { ok: false, reason: paused ? 'run is paused' : 'run is not paused' };
  return { ok: true, state: { ...state, paused } };
}

const createHost: CreateHost = async () => {
  const runs = new Map<string, RunState>();

  const apply = (run: string, step: Step): Outcome => {
    if (!step.ok) return { ok: false, reason: step.reason };
    runs.set(run, step.state);
    return { ok: true };
  };
  const report = (r: TaskReport) => async (run: string, task: number): Promise<Outcome> =>
    apply(run, stepTask(runs.get(run), r, task));

  return {
    start: async (run) => apply(run, stepStart(runs.get(run))),
    taskStarted: report('taskStarted'),
    taskCompleted: report('taskCompleted'),
    taskFailed: report('taskFailed'),
    taskEvicted: report('taskEvicted'),
    taskRequeued: report('taskRequeued'),
    taskRetried: report('taskRetried'),
    cancel: async (run) => apply(run, stepCancel(runs.get(run))),
    cancelTask: async (run, task) => apply(run, stepCancelTask(runs.get(run), task)),
    run: async (run) => {
      const s = runs.get(run);
      if (!s) return null;
      return { status: s.status, task0: s.tasks[0], task1: s.tasks[1], task2: s.tasks[2] };
    },
  };
};

export default createHost;

import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('fresh system has no runs; commands on unknown runs are refused', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal(await h.run('a'), null);
});

test('start creates a queued run; duplicate start refused', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.start('a')).ok, false);
});

test('happy path to completed, then everything refused', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) assert.equal((await h.taskStarted('a', t)).ok, true);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskCompleted('a', 0);
  await h.taskCompleted('a', 1);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskCompleted('a', 2);
  assert.equal((await h.run('a'))!.status, 'completed');
  assert.equal((await h.start('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
});

test('failure makes the run failed, but it still accepts commands', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 1);
  await h.taskFailed('a', 1);
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.equal((await h.taskStarted('a', 0)).ok, true);
  assert.equal((await h.run('a'))!.status, 'failed');
});

test('retry: a failed task is queued again and the run can complete', async () => {
  const h = await createHost();
  await h.start('a');
  assert.equal((await h.taskRetried('a', 0)).ok, false);
  await h.taskStarted('a', 0);
  assert.equal((await h.taskRetried('a', 0)).ok, false);
  await h.taskFailed('a', 0);
  assert.equal((await h.taskRetried('a', 3)).ok, false);
  assert.deepEqual(await h.taskRetried('a', 0), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskCompleted('a', t); }
  assert.equal((await h.run('a'))!.status, 'completed');
  assert.equal((await h.taskRetried('a', 0)).ok, false);
});

test('all tasks failed: run failed, still retryable', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskFailed('a', t); }
  assert.equal((await h.run('a'))!.status, 'failed');
  assert.equal((await h.cancel('a')).ok, false); // nothing in flight
  assert.equal((await h.taskRetried('a', 2)).ok, true);
  assert.equal((await h.run('a'))!.status, 'failed');
});

test('cancel on a failed run keeps the failed task, which can be retried', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 0);
  await h.taskFailed('a', 0);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled' });
  await h.taskRetried('a', 0);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskStarted('a', 0);
  await h.taskCompleted('a', 0);
  assert.equal((await h.run('a'))!.status, 'cancelled');
  assert.equal((await h.taskStarted('a', 1)).ok, false);
});

test('eviction and requeue; all evicted gives evicted', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskEvicted('a', t); }
  assert.equal((await h.run('a'))!.status, 'evicted');
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.taskRequeued('a', 0)).ok, true);
  assert.equal((await h.run('a'))!.status, 'running');
});

test('cancel: in-flight become cancelled, completed stay', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 0);
  await h.taskCompleted('a', 0);
  await h.taskStarted('a', 1);
  await h.taskEvicted('a', 1);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
});

test('bad task numbers and bad moves are refused and change nothing', async () => {
  const h = await createHost();
  await h.start('a');
  const before = await h.run('a');
  for (const t of [3, -1, 1.5, NaN, '0' as unknown as number]) assert.equal((await h.taskStarted('a', t)).ok, false);
  assert.equal((await h.taskCompleted('a', 0)).ok, false);
  assert.equal((await h.taskRequeued('a', 0)).ok, false);
  assert.deepEqual(await h.run('a'), before);
});

test('cancelTask cancels one in-flight task; final tasks refused', async () => {
  const h = await createHost();
  assert.equal((await h.cancelTask('a', 0)).ok, false);
  await h.start('a');
  assert.deepEqual(await h.cancelTask('a', 1), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'running', task0: 'queued', task1: 'cancelled', task2: 'queued' });
  assert.equal((await h.cancelTask('a', 1)).ok, false); // already cancelled
  assert.equal((await h.cancelTask('a', 3)).ok, false);
  await h.taskStarted('a', 0);
  await h.taskCompleted('a', 0);
  assert.equal((await h.cancelTask('a', 0)).ok, false); // completed is final
  await h.taskStarted('a', 2);
  await h.taskEvicted('a', 2);
  assert.deepEqual(await h.cancelTask('a', 2), { ok: true }); // evicted is in flight
  assert.deepEqual(await h.run('a'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.taskRetried('a', 0)).ok, false);
});

test('cancelTask on a failed run; failed task cannot be cancelled', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 0);
  await h.taskFailed('a', 0);
  assert.equal((await h.cancelTask('a', 0)).ok, false);
  assert.equal((await h.cancelTask('a', 1)).ok, true);
  assert.equal((await h.cancelTask('a', 2)).ok, true);
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled' });
});

test('cancelling every task one by one cancels the run', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) await h.cancelTask('a', t);
  assert.equal((await h.run('a'))!.status, 'cancelled');
  assert.equal((await h.cancel('a')).ok, false);
});

test('systems are independent', async () => {
  const a = await createHost();
  const b = await createHost();
  await a.start('x');
  assert.equal(await b.run('x'), null);
});

