'use strict';

// SAM v2 strict spec of one run's stateful core (src/host.impl.ts:
// stepStart / stepTask / stepCancel / stepCancelTask / stepPause).
// status 'none' = run never started.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'none', t0: 'none', t1: 'none', t2: 'none', paused: false };

const TASKS = ['t0', 't1', 't2'];
const MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
  TASK_RETRIED: ['failed', 'queued'],
};
const inFlight = (s) => s === 'queued' || s === 'running' || s === 'evicted';
// a failed run still accepts commands (retry); only these refuse everything
const isClosed = (s) => s === 'completed' || s === 'cancelled';
const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.some((t) => t === 'failed')) return 'failed';
  if (ts.some(inFlight)) return 'running';
  return 'cancelled';
};

// Commit new task statuses and the derived run status; paused is untouched.
const commitTasks = (ts, next, unchanged) => {
  next.t0 = ts[0];
  next.t1 = ts[1];
  next.t2 = ts[2];
  next.status = derive(ts);
  unchanged('paused');
};

const taskDomain = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];
const taskSchema = { task: { type: 'number' } };

const taskAcceptor = (name) => (model) => (proposal, { reject, next, unchanged }) => {
  if (model.status === 'none') return reject('unknown-run');
  if (isClosed(model.status)) return reject('run-closed');
  const i = proposal.task;
  if (i !== 0 && i !== 1 && i !== 2) return reject('no-such-task');
  if (name === 'TASK_STARTED' && model.paused) return reject('run-paused');
  const [from, to] = MOVES[name];
  const ts = TASKS.map((k) => model[k]);
  if (ts[i] !== from) return reject('illegal-move');
  ts[i] = to;
  commitTasks(ts, next, unchanged);
};

const pauseAcceptor = (paused) => (model) => (proposal, { reject, next, unchanged }) => {
  if (model.status === 'none') return reject('unknown-run');
  if (isClosed(model.status)) return reject('run-closed');
  if (model.paused === paused) return reject(paused ? 'already-paused' : 'not-paused');
  next.paused = paused;
  unchanged('status', 't0', 't1', 't2');
};

const taskAction = () => ({ action: (data = {}) => ({ ...data }), schema: taskSchema, domain: taskDomain });
const plainAction = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      t0: { type: 'string' },
      t1: { type: 'string' },
      t2: { type: 'string' },
      paused: { type: 'boolean' },
    },
    actions: {
      START: plainAction(),
      TASK_STARTED: taskAction(),
