        if (model.status !== 'none') return reject('run-exists');
        next.status = 'queued';
        next.t0 = 'queued';
        next.t1 = 'queued';
        next.t2 = 'queued';
        next.paused = false;
      },
      TASK_STARTED: taskAcceptor('TASK_STARTED'),
      TASK_COMPLETED: taskAcceptor('TASK_COMPLETED'),
      TASK_FAILED: taskAcceptor('TASK_FAILED'),
      TASK_EVICTED: taskAcceptor('TASK_EVICTED'),
      TASK_REQUEUED: taskAcceptor('TASK_REQUEUED'),
      TASK_RETRIED: taskAcceptor('TASK_RETRIED'),
