const CLOSED = ['completed', 'cancelled'];
const tasks = (s) => [s.t0, s.t1, s.t2];
const sameTasks = (a, b) => a.status === b.status && a.t0 === b.t0 && a.t1 === b.t1 && a.t2 === b.t2;
const same = (a, b) => sameTasks(a, b) && a.paused === b.paused;
const open = (s) => s.status !== 'none' && !CLOSED.includes(s.status);

